async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  let fragments = [];
  let line = 1;
  let delivered = 0;
  let stopped = false;

  async function processLine(text) {
    if (text.endsWith("\r")) text = text.slice(0, -1);

    if (/^[\t ]*$/.test(text)) {
      line++;
      return;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${line}`);
      error.code = "BAD_LINE";
      error.line = line;
      throw error;
    }

    const currentLine = line++;
    delivered++;

    if ((await deliver(value, currentLine)) === false) {
      stopped = true;
    }
  }

  async function consume(text) {
    let start = 0;

    while (!stopped) {
      const end = text.indexOf("\n", start);
      if (end === -1) break;

      fragments.push(text.slice(start, end));
      const completeLine =
        fragments.length === 1 ? fragments[0] : fragments.join("");
      fragments = [];

      await processLine(completeLine);
      start = end + 1;
    }

    if (!stopped && start < text.length) {
      fragments.push(text.slice(start));
    }
  }

  try {
    while (!stopped) {
      const chunk = await input.read();
      if (chunk === null) break;
      await consume(decoder.decode(chunk, { stream: true }));
    }

    if (!stopped) {
      await consume(decoder.decode());

      if (!stopped && fragments.length > 0) {
        const finalLine =
          fragments.length === 1 ? fragments[0] : fragments.join("");
        fragments = [];
        await processLine(finalLine);
      }
    }

    return delivered;
  } finally {
    await input.close();
  }
}
